+          </button>}
+        </>}
+      >
+        <p>{wiki ? "Search the Wiki for a page that covers this path." : "Search OpenSpec for a spec or change that covers this path."}</p>
+        {draftError && <p role="alert" className="tone-danger">{draftError}</p>}
+      </EmptyState>}
