+        <ul className="metaproject-rgraph-legend" aria-label="Graph legend">
+          {legend.nodeKinds.map((item) => (
+            <li key={item.kind}>
+              <span className={`metaproject-rgraph-swatch is-${item.kind}`} aria-hidden="true" />
+              {item.label}
