+            <li key={item.style}>
+              <span className={`metaproject-rgraph-line is-${item.style}`} aria-hidden="true" />
+              {item.label}: {item.kinds.join(", ")}
+            </li>
+          ))}
+        </ul>
+      )}
+    </div>
+  );
+}

