+.metaproject-rgraph.is-busy .metaproject-rgraph-canvas { opacity: 0.55; }
+.metaproject-rgraph-viewport { position: absolute; inset: 0; }
+
+.metaproject-rgraph-zoom {
+  display: flex;
+  flex: none;
+  gap: var(--sp-1);
+  margin-inline-start: auto;
+}
+/* Host controls (the explorer's Filters button) sit just left of the zoom controls. */
+.metaproject-rgraph-actions { display: flex; flex: none; align-items: center; gap: var(--sp-1); margin-inline-start: auto; }
