+      expect(shown).toBe(COLUMN_CAP);
+      expect(overflow.hidden).toBe(overflow.total - COLUMN_CAP);
+    }
+    expect(new Set(layout.overflow.map((item) => item.column)).size).toBe(layout.overflow.length);
